</div>
</div>
<!-- Meaning of Motif Accordion / Note -->
<div class="p-space-sm bg-surface-container rounded-xl flex flex-col gap-1">
<span class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold flex items-center gap-1">
<span class="material-symbols-outlined text-[14px]">auto_stories</span> Makna Filosofis Motif
        </span>
<p class="font-body-sm text-body-sm text-on-surface-variant leading-relaxed" id="previewPhilosophy">
          Parang melambangkan ombak samudera yang pantang menyerah dan keteguhan ksatria. Garis diagonal tegas mencerminkan wibawa pemimpin luhur.
        </p>
</div>
<!-- Quick Actions for Selected Item -->
<div class="flex items-center gap-space-sm pt-space-xs">
<button class="flex-1 bg-surface-container-high text-primary hover:bg-primary hover:text-on-primary py-space-xs rounded-xl font-label-lg text-label-lg font-bold transition-all flex items-center justify-center gap-1" onclick="quickAdjustStock()">
<span class="material-symbols-outlined text-[18px]">add_box</span> Tambah Stok
        </button>
<button class="flex-1 bg-primary-container text-on-primary hover:bg-secondary py-space-xs rounded-xl font-label-lg text-label-lg font-bold transition-all flex items-center justify-center gap-1" onclick="printCert()">
<span class="material-symbols-outlined text-[18px]">print</span> Cetak Barcode
        </button>
</div>
</div>
</div>
<!-- Notification Toast Container -->
<div class="fixed bottom-6 right-6 z-50 transform translate-y-32 opacity-0 transition-all duration-300 pointer-events-none" id="toastNotification">
<div class="bg-primary text-on-primary px-space-lg py-space-sm rounded-xl shadow-xl flex items-center gap-space-sm">
<span class="material-symbols-outlined text-secondary-container" id="toastIcon">check_circle</span>
<div class="flex flex-col">
<span class="font-label-md text-label-md font-bold" id="toastTitle">Berhasil</span>
<span class="font-body-sm text-body-sm text-surface-container-highest" id="toastMessage">Operasi inventaris selesai</span>
</div>
</div>
</div>
<!-- Modal Tambah / Edit Produk Baru (Hidden by Default) -->
<div class="fixed inset-0 z-50 bg-primary/40 backdrop-blur-sm flex items-center justify-center p-space-md opacity-0 pointer-events-none transition-opacity duration-200" id="crudModal">
<div class="bg-surface-container-lowest max-w-xl w-full rounded-xl shadow-2xl p-space-lg flex flex-col gap-space-md max-h-[921px] overflow-y-auto">
<div class="flex items-center justify-between pb-space-sm bg-surface-container-low -mx-space-lg -mt-space-lg p-space-md rounded-t-xl">
<div class="flex items-center gap-space-xs">
<span class="material-symbols-outlined text-secondary">inventory</span>
<h2 class="font-title-lg text-title-lg text-primary font-bold" id="modalTitle">Entri Wastra Baru</h2>
</div>
<button class="w-8 h-8 rounded-lg bg-surface-container flex items-center justify-center text-on-surface-variant hover:text-primary" onclick="closeModal()">
<span class="material-symbols-outlined text-[20px]">close</span>
</button>
</div>
<form class="flex flex-col gap-space-md" id="productForm" onsubmit="handleFormSubmit(event)">
<div class="grid grid-cols-2 gap-space-md">
<div class="flex flex-col gap-1">
<label class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold">Kode SKU</label>
<input class="bg-surface-container-low px-space-md py-space-xs rounded-lg text-on-surface font-body-sm text-body-sm focus:outline-none" id="modalSku" placeholder="#JB-006" required="" type="text"/>
</div>
<div class="flex flex-col gap-1">
<label class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold">Kategori Produk</label>
<select class="bg-surface-container-low px-space-md py-space-xs rounded-lg text-on-surface font-body-sm text-body-sm focus:outline-none" id="modalCategory" required="">
<option value="Batik Tulis Pria">Batik Tulis Pria</option>
<option value="Batik Cap Wanita">Batik Cap Wanita</option>
<option value="Kain Jarik Mahakarya">Kain Jarik Mahakarya</option>
<option value="Batik Tulis Bespoke">Batik Tulis Bespoke</option>
<option value="Modern Outer">Modern Outer</option>
</select>
</div>
</div>
<div class="flex flex-col gap-1">
<label class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold">Nama Produk &amp; Motif</label>
<input class="bg-surface-container-low px-space-md py-space-xs rounded-lg text-on-surface font-body-sm text-body-sm focus:outline-none" id="modalName" placeholder="Contoh: Kemeja Parang Barong Sutra Keraton" required="" type="text"/>
</div>
<div class="grid grid-cols-2 gap-space-md">
<div class="flex flex-col gap-1">
<label class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold">Harga Ritel (IDR)</label>
<input class="bg-surface-container-low px-space-md py-space-xs rounded-lg text-on-surface font-body-sm text-body-sm focus:outline-none" id="modalPrice" placeholder="1850000" required="" type="number"/>
</div>
<div class="flex flex-col gap-1">
<label class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold">Jumlah Stok (Helai)</label>
<input class="bg-surface-container-low px-space-md py-space-xs rounded-lg text-on-surface font-body-sm text-body-sm focus:outline-none" id="modalStock" min="0" placeholder="5" required="" type="number"/>
</div>
</div>
<div class="grid grid-cols-2 gap-space-md">
<div class="flex flex-col gap-1">
<label class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold">Lokasi Gudang</label>
<select class="bg-surface-container-low px-space-md py-space-xs rounded-lg text-on-surface font-body-sm text-body-sm focus:outline-none" id="modalWarehouse">
<option value="Solo Atelier">Solo Atelier (Keraton)</option>
<option value="Yogyakarta Vault">Yogyakarta Vault (Kotagede)</option>
</select>
</div>
<div class="flex flex-col gap-1">
<label class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold">Status Publikasi</label>
<select class="bg-surface-container-low px-space-md py-space-xs rounded-lg text-on-surface font-body-sm text-body-sm focus:outline-none" id="modalStatus">
<option value="Aktif">Aktif (Katalog Publik)</option>
<option value="Draft">Draft (Arsip Internal)</option>
</select>
</div>
</div>
<div class="flex flex-col gap-1">
<label class="font-label-sm text-label-sm uppercase tracking-wider text-secondary font-bold">Catatan Canting &amp; Filosofi Singkat</label>
<textarea class="bg-surface-container-low px-space-md py-space-xs rounded-lg text-on-surface font-body-sm text-body-sm focus:outline-none" id="modalNotes" placeholder="Tuliskan makna motif atau profil perajin canting..." rows="2"></textarea>
</div>
<div class="flex items-center justify-end gap-space-sm pt-space-xs">
<button class="px-space-md py-space-xs rounded-xl bg-surface-container text-on-surface font-label-lg text-label-lg hover:bg-surface-container-high transition-colors" onclick="closeModal()" type="button">
            Batal
          </button>
<button class="px-space-lg py-space-xs rounded-xl bg-primary text-on-primary font-label-lg text-label-lg font-bold shadow-md hover:bg-primary-container transition-all" type="submit">
            Simpan Wastra
          </button>
</div>
</form>
</div>
</div>
</div>
<script>
  // Product detailed dataset for dynamic interactive preview & quick editing
  const productData = {
    '#JB-001': {
      sku: '#JB-001',
      name: 'Kemeja Parang Rusak Slimfit',
      category: 'Batik Tulis Pria',
      price: 'Rp 1.850.000',
      stockTotal: '3 helai',
      stockSolo: '2 Helai',
      stockYogya: '1 Helai',
      artisan: 'Mpu Sutikno - Surakarta',
      processTime: '45 Hari Canting',
      philosophy: 'Parang melambangkan ombak samudera yang pantang menyerah dan keteguhan ksatria. Garis diagonal tegas mencerminkan wibawa pemimpin luhur.',
      imagePrompt: 'High-end studio shot of luxurious deep brown and golden soga batik silk shirt featuring intricate hand-drawn Parang Rusak motif draped over natural mahogany background'
    },
    '#JB-002': {
      sku: '#JB-002',
      name: 'Kimono Outer Kawung Soga',
      category: 'Modern Outer',
      price: 'Rp 1.450.000',
      stockTotal: '14 helai',
      stockSolo: '9 Helai',
      stockYogya: '5 Helai',
      artisan: 'Ibu Ningsih - Sleman',
      processTime: '21 Hari Pewarnaan Alami',
      philosophy: 'Kawung berbentuk penampang buah aren empat penjuru melambangkan kesucian hati, ketenteraman jiwa, dan harmoni semesta.',
      imagePrompt: 'Model wearing contemporary haute couture kimono outer featuring rhythmic geometric Kawung Picis motif in rich caramel soga brown and warm cream tones'
    },
    '#JB-003': {
      sku: '#JB-003',
      name: 'Kain Jarik Sekar Jagad Indigo',
      category: 'Kain Jarik Mahakarya',
      price: 'Rp 3.200.000',
      stockTotal: '1 helai',
      stockSolo: '1 Helai',
      stockYogya: '0 Helai',
      artisan: 'KRT Hardjodiningrat - Imogiri',
      processTime: '90 Hari Canting Alus',
      philosophy: 'Sekar Jagad bermakna bunga keindahan seluruh penjuru dunia. Menyiratkan keberagaman yang menyatu dalam aura kedamaian nan agung.',
      imagePrompt: 'Museum-grade textile flatlay of rare indigo and terracotta Sekar Jagad batik cloth displaying floral islands and intricate celestial motifs'
    },
    '#JB-004': {
      sku: '#JB-004',
      name: 'Kemeja Batik Truntum Garuda',
      category: 'Batik Tulis Bespoke',
      price: 'Rp 1.650.000',
      stockTotal: '8 helai',
      stockSolo: '5 Helai',
      stockYogya: '3 Helai',
      artisan: 'Yu Karsiti - Laweyan Solo',
      processTime: '30 Hari Canting Teliti',
      philosophy: 'Truntum diciptakan Ratu Kencana perlambang cinta yang bersemi kembali (tumaruntum), dipadu ketangguhan sayap garuda sang pelindung jagad.',
      imagePrompt: 'Refined close-up of dark soga batik silk shirt patterned with Truntum star constellations and royal mythical Garuda wing ornaments'
    },
    '#JB-005': {
      sku: '#JB-005',
      name: 'Blouse Megamendung Pesisir',
      category: 'Batik Cap Wanita',
      price: 'Rp 850.000',
      stockTotal: '22 helai',
      stockSolo: '14 Helai',
      stockYogya: '8 Helai',
      artisan: 'Sanggar Trusmi Pesisir',
      processTime: '14 Hari Pewarnaan Gradasi',
      philosophy: 'Bentuk awan mendung tujuh gradasi yang meneduhkan hati insan di kala amarah, membawa berkah hujan kesejukan.',
      imagePrompt: 'High fashion editorial model wearing vibrant blue and crimson Megamendung cloud patterned batik blouse with crisp modern tailoring'
    }
  };

  // Select Row & Update Side Drawer Preview
  function selectProductRow(sku) {
    const item = productData[sku];
    if (!item) return;

    // Highlight row
    document.querySelectorAll('#inventoryTableBody tr').forEach(tr => {
      tr.classList.remove('bg-surface-container-high/60');
    });
    const selectedTr = document.querySelector(`[data-sku="${sku}"]`);
    if (selectedTr) {
      selectedTr.classList.add('bg-surface-container-high/60');
    }

    // Update Preview Drawer
    document.getElementById('previewSkuBadge').textContent = item.sku;
    document.getElementById('previewTitle').textContent = item.name;
    document.getElementById('previewCategory').textContent = item.category + ' • Atelier Heritage';
    document.getElementById('previewPrice').textContent = item.price;
    document.getElementById('previewStockSolo').textContent = item.stockSolo;
    document.getElementById('previewStockYogya').textContent = item.stockYogya;
    document.getElementById('previewArtisan').textContent = item.artisan;
    document.getElementById('previewProcessTime').textContent = item.processTime;
    document.getElementById('previewPhilosophy').textContent = item.philosophy;

    // Change image prompt for generative compliance
    const imgEl = document.getElementById('previewImage');
    imgEl.setAttribute('data-alt', item.imagePrompt);
  }

  // Filter Table Real-time
  function filterTable() {
    const query = document.getElementById('searchInput').value.toLowerCase();
    const kategori = document.getElementById('kategoriFilter').value;
    const statusStok = document.getElementById('statusStokFilter').value;

    const rows = document.querySelectorAll('#inventoryTableBody tr');
    let visibleCount = 0;

    rows.forEach(row => {
      const sku = row.getAttribute('data-sku').toLowerCase();
      const name = row.getAttribute('data-name').toLowerCase();
      const cat = row.getAttribute('data-category');
      const stockType = row.getAttribute('data-stock-type');

      const matchesSearch = sku.includes(query) || name.includes(query);
      const matchesCategory = (kategori === 'Semua' || cat === kategori);
      const matchesStock = (statusStok === 'Semua' || stockType === statusStok);

      if (matchesSearch && matchesCategory && matchesStock) {
        row.style.display = '';
        visibleCount++;
      } else {
        row.style.display = 'none';
      }
    });

    document.getElementById('activeFilterBadge').textContent = `Menampilkan ${visibleCount} Data Terpilih`;
  }

  // Multi-Select Checkboxes
  function toggleSelectAll(master) {
    const checkboxes = document.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = master.checked;
    });
    showToast('Pilihan Diperbarui', `${master.checked ? 'Semua' : 'Batal'} produk terpilih.`);
  }

  // Modal Open / Close
  function openAddModal() {
    document.getElementById('modalTitle').textContent = 'Entri Wastra Baru';
    document.getElementById('productForm').reset();
    document.getElementById('modalSku').value = '#JB-00' + (Object.keys(productData).length + 1);
    const modal = document.getElementById('crudModal');
    modal.classList.remove('opacity-0', 'pointer-events-none');
    modal.classList.add('opacity-100', 'pointer-events-auto');
  }

  function editProduct(sku) {
    const item = productData[sku];
    if (!item) return;

    document.getElementById('modalTitle').textContent = `Ubah Data Produk (${sku})`;
    document.getElementById('modalSku').value = item.sku;
    document.getElementById('modalName').value = item.name;
    document.getElementById('modalCategory').value = item.category;
    document.getElementById('modalPrice').value = item.price.replace(/[^0-9]/g, '');
    document.getElementById('modalStock').value = parseInt(item.stockTotal);
    document.getElementById('modalNotes').value = item.philosophy;

    const modal = document.getElementById('crudModal');
    modal.classList.remove('opacity-0', 'pointer-events-none');
    modal.classList.add('opacity-100', 'pointer-events-auto');
  }

  function closeModal() {
    const modal = document.getElementById('crudModal');
    modal.classList.add('opacity-0', 'pointer-events-none');
    modal.classList.remove('opacity-100', 'pointer-events-auto');
  }

  function handleFormSubmit(e) {
    e.preventDefault();
    const sku = document.getElementById('modalSku').value;
    const name = document.getElementById('modalName').value;
    closeModal();
    showToast('Penyimpanan Sukses', `Wastra ${sku} (${name}) berhasil diperbarui dalam stok.`);
  }

  // CRUD Delete
  function deleteProduct(sku) {
    if (confirm(`Yakin ingin mengarsipkan wastra dengan ID ${sku} dari katalog inventaris?`)) {
      const row = document.querySelector(`[data-sku="${sku}"]`);
      if (row) {
        row.style.opacity = '0.3';
        setTimeout(() => {
          row.remove();
          filterTable();
          showToast('Produk Dihapus', `Katalog ${sku} dipindahkan ke arsip.`);
        }, 300);
      }
    }
  }

  // Quick Action Utilities
  function quickAdjustStock() {
    const currentSku = document.getElementById('previewSkuBadge').textContent;
    showToast('Penyesuaian Cepat', `Form restok cepat untuk ${currentSku} dibuka.`);
  }

  function printCert() {
    const currentSku = document.getElementById('previewSkuBadge').textContent;
    showToast('Cetak Berhasil', `Barcode keaslian ${currentSku} dikirim ke pencetak thermal.`);
  }

  function exportCSV() {
    showToast('Ekspor Data', 'Mengunduh inventaris_juraganbatik_okt2024.csv');
  }

  function refreshData() {
    const icon = document.getElementById('syncIcon');
    icon.classList.add('animate-spin');
    setTimeout(() => {
      icon.classList.remove('animate-spin');
      showToast('Sinkronisasi Selesai', 'Data stok Solo & Yogyakarta telah mutakhir.');
    }, 900);
  }

  // Toast Notification System
  function showToast(title, msg) {
    const toast = document.getElementById('toastNotification');
    document.getElementById('toastTitle').textContent = title;
    document.getElementById('toastMessage').textContent = msg;

    toast.classList.remove('translate-y-32', 'opacity-0');
    toast.classList.add('translate-y-0', 'opacity-100');

    setTimeout(() => {
      toast.classList.add('translate-y-32', 'opacity-0');
      toast.classList.remove('translate-y-0', 'opacity-100');
    }, 3200);
  }
</script></main></div></body></html>